vec3 palette(float t) {
    vec3 a = vec3(0.5, 0.5, 0.5);
    vec3 b = vec3(0.5, 1.5, 2.5);
    vec3 c = vec3(0.0, 1.0, 0.5);
    vec3 d = vec3(0.153, 0.56, 0.557);

    return a + b * cos(10.0 * (c * t + d));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;
    vec2 uv0 = uv; // Save original UVs
    vec3 finalColor = vec3(0.0);

    // Audio Reactivity
    float audio = texture(iChannel0, vec2(0.01, uv.y * 0.5 + 0.5)).r; // Sample audio
    float audioFactor = 0.2 + audio * 0.8; // Scale audio effect subtly

    for (float i = 0.0; i < 5.0; ++i) {
        // Controlled UV transformations
        float angle = iTime * 0.5 + i * 0.2;
        mat2 rot = mat2(cos(angle), -sin(angle), sin(angle), cos(angle));
        uv *= rot;
        uv = fract(uv * 1.5) - 0.5;

        // Distance calculation
        float d = length(uv) * exp(-length(uv0) + i * 0.3);
        vec3 col = palette(length(uv0) + i * 0.4 + iTime * 0.2);

        // Subtle sinusoidal modulation
        d = sin(d * 8.0 + iTime * 0.3 + audioFactor) / 8.0;
        d = abs(d);
        d = pow(0.01 / d, 1.2);

        // Blend colors softly
        finalColor += col * d * (0.8 + 0.2 * audioFactor);
    }

    // Glow and smoothing
    finalColor = pow(finalColor, vec3(0.9));

    // Output final color
    fragColor = vec4(finalColor, 1.0);
}
